@startuml

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Client {
  + NIN : string
  + TIN : string
  + Name : string
  + Address : string
}

class BicycleModel {
  + Name : string
  + Type : BicycleType
  + Gears : int
}

class Bicycle {
  + IdNumber : string
}

class Store {
  + Name : string
  + Address : string
}

class Reservation {
  + PickupDate : date
}

class Rental {
  + ReturnDate : date
}

BicycleModel "1" -- "*" Bicycle
Bicycle "0..*" -- "1" BicycleModel
Store "1" -- "*" Reservation
Store "1" -- "*" Rental
Client "1" -- "*" Reservation
Client "1" -- "*" Rental
BicycleModel "1" -- "*" Reservation
Bicycle "1" -- "0..1" Rental
Reservation "0..1" -- "0..1" Rental

@enduml

